package com.slayerspeed.calculation;

public enum Confidence
{
	NO_DATA("No data"),
	LOW("Low"),
	MEDIUM("Medium"),
	HIGH("High");

	private final String displayName;

	Confidence(String displayName)
	{
		this.displayName = displayName;
	}

	public String getDisplayName()
	{
		return displayName;
	}

	public static Confidence fromSample(int completedTasks, int progressUnits)
	{
		if (completedTasks <= 0 || progressUnits <= 0)
		{
			return NO_DATA;
		}
		if (completedTasks < 2 || progressUnits < 30)
		{
			return LOW;
		}
		if (completedTasks < 5)
		{
			return MEDIUM;
		}
		return HIGH;
	}
}

package com.slayerspeed.calculation;

/** Recent windows are opt-in and only use eligible retained runs. */
public enum EstimateWindow
{
    LIFETIME(0, "Lifetime"),
    RECENT_5(5, "Recent 5"),
    RECENT_10(10, "Recent 10"),
    RECENT_25(25, "Recent 25");

    private final int size;
    private final String label;
    EstimateWindow(int size, String label) { this.size = size; this.label = label; }
    public int getSize() { return size; }
    @Override public String toString() { return label; }
}

package com.slayerspeed.calculation;

import com.slayerspeed.model.*;
import java.util.Comparator;
import java.util.List;
import java.util.stream.Collectors;

/** Select after eligibility and location grouping, never truncate raw runs first. */
public final class HistoryEstimateService
{
    public TaskStatistics select(TaskStatistics history, EstimateWindow window)
    {
        if (history == null || window == null || window == EstimateWindow.LIFETIME) { return history; }
        TaskStatistics selected = new TaskStatistics(history.getTaskName(), history.getTaskLocation(),
            history.getEncounterProfileId(), history.getEncounterProfileName());
        List<TaskRun> runs = history.getRecentRuns().stream()
            .filter(run -> new TaskKey(run.getTaskName(), null, run.getEncounterProfileId()).equals(
                new TaskKey(history.getTaskName(), null, history.getEncounterProfileId()))
                && (history.getTaskLocation() == null || new TaskKey(run.getTaskName(), run.getTaskLocation())
                    .equals(new TaskKey(history.getTaskName(), history.getTaskLocation()))))
            .filter(run -> run.getStatus() == TaskRunStatus.COMPLETED && !run.isExcludedFromAverages()
                && run.getTaskProgressUnits() > 0 && run.getActiveMillis() > 0)
            .sorted(Comparator.comparingLong(TaskRun::getCompletedAtMillis).reversed()
                .thenComparing(TaskRun::getId))
            .limit(window.getSize()).collect(Collectors.toList());
        // addRun prepends, so retain the selected global timestamp ordering.
        for (int index = runs.size() - 1; index >= 0; index--)
        {
            selected.addRun(runs.get(index), window.getSize());
        }
        return selected;
    }

    public String scope(TaskStatistics selected, EstimateWindow window)
    {
        if (window == null || window == EstimateWindow.LIFETIME) { return "Lifetime history"; }
        int available = selected == null ? 0 : selected.getRecentRuns().size();
        return "Recent " + available + "/" + window.getSize() + " eligible runs";
    }

    public TaskEstimate estimate(TaskStatistics selected, EstimateWindow window, int remaining)
    {
        return new TaskEstimateService().calculate(remaining, 0, 0,
            selected == null ? 0 : selected.getTotalTaskProgressUnits(),
            selected == null ? 0 : selected.getTotalActiveMillis(), 10, false,
            selected == null ? 0 : selected.getCompletedTaskCount(),
            scope(selected, window));
    }
}

package com.slayerspeed.calculation;

import java.time.Duration;
import java.util.Locale;
import java.util.OptionalDouble;

public final class KphCalculator
{
	private static final double MILLIS_PER_HOUR = 3_600_000.0;

	private KphCalculator()
	{
	}

	public static OptionalDouble ratePerHour(long amount, long activeMillis)
	{
		if (amount < 0 || activeMillis <= 0)
		{
			return OptionalDouble.empty();
		}
		return OptionalDouble.of(amount * MILLIS_PER_HOUR / activeMillis);
	}

	public static OptionalDouble literalKph(int actualKills, long activeMillis)
	{
		return ratePerHour(actualKills, activeMillis);
	}

	public static OptionalDouble effectiveKph(int progressUnits, long activeMillis)
	{
		return ratePerHour(progressUnits, activeMillis);
	}

	public static OptionalDouble slayerXpPerHour(int slayerXp, long activeMillis)
	{
		return ratePerHour(slayerXp, activeMillis);
	}

	public static OptionalDouble xpPerKill(int slayerXp, int actualKills)
	{
		return ratio(slayerXp, actualKills);
	}

	public static OptionalDouble xpPerTaskUnit(int slayerXp, int progressUnits)
	{
		return ratio(slayerXp, progressUnits);
	}

	public static OptionalDouble cannonballsPerKill(int cannonballs, int actualKills)
	{
		return ratio(cannonballs, actualKills);
	}

	public static OptionalDouble cannonballsPerTaskUnit(int cannonballs, int progressUnits)
	{
		return ratio(cannonballs, progressUnits);
	}

	public static OptionalDouble estimatedCannonballs(int taskSize, double cannonballsPerTaskUnit)
	{
		if (taskSize <= 0 || !Double.isFinite(cannonballsPerTaskUnit) || cannonballsPerTaskUnit < 0.0)
		{
			return OptionalDouble.empty();
		}
		return OptionalDouble.of(taskSize * cannonballsPerTaskUnit);
	}

	private static OptionalDouble ratio(int numerator, int denominator)
	{
		if (numerator < 0 || denominator <= 0)
		{
			return OptionalDouble.empty();
		}
		return OptionalDouble.of((double) numerator / denominator);
	}

	public static OptionalDouble etaMillis(int remainingAmount, double effectiveKph)
	{
		if (remainingAmount < 0 || !Double.isFinite(effectiveKph) || effectiveKph <= 0)
		{
			return OptionalDouble.empty();
		}
		return OptionalDouble.of(remainingAmount * MILLIS_PER_HOUR / effectiveKph);
	}

	public static String formatRate(OptionalDouble rate)
	{
		return rate.isPresent() ? String.format(Locale.ENGLISH, "%.1f", rate.getAsDouble()) : "--";
	}

	public static String formatXpRate(OptionalDouble rate)
	{
		if (!rate.isPresent())
		{
			return "--";
		}
		double value = Math.max(0.0, rate.getAsDouble());
		if (value >= 1_000_000.0)
		{
			return String.format(Locale.ENGLISH, "%.2fm", value / 1_000_000.0);
		}
		if (value >= 1_000.0)
		{
			return String.format(Locale.ENGLISH, "%.1fk", value / 1_000.0);
		}
		return String.format(Locale.ENGLISH, "%.0f", value);
	}

	public static String formatDuration(OptionalDouble millis)
	{
		if (!millis.isPresent())
		{
			return "--";
		}
		long seconds = Math.max(0L, Math.round(millis.getAsDouble() / 1000.0));
		Duration duration = Duration.ofSeconds(seconds);
		long hours = duration.toHours();
		long minutes = duration.minusHours(hours).toMinutes();
		long remainingSeconds = duration.minusHours(hours).minusMinutes(minutes).getSeconds();
		if (hours == 0 && minutes < 10)
		{
			return minutes > 0
				? String.format(Locale.ENGLISH, "%dm %02ds", minutes, remainingSeconds)
				: remainingSeconds + "s";
		}
		return hours > 0 ? String.format(Locale.ENGLISH, "%dh %02dm", hours, minutes) : minutes + "m";
	}

	public static String formatCannonballEstimate(OptionalDouble cannonballs)
	{
		return cannonballs.isPresent()
			? Long.toString((long) Math.ceil(Math.max(0.0, cannonballs.getAsDouble())))
			: "--";
	}
}

package com.slayerspeed.calculation;

import java.util.OptionalDouble;

/** Immutable numeric result and the evidence behind it. */
public final class TaskEstimate
{
    public enum Source { UNAVAILABLE, LIVE, HISTORY, BLENDED }
    private final Source source;
    private final OptionalDouble rate;
    private final OptionalDouble etaMillis;
    private final String scope;
    private final int fullTasks;
    private final String reason;

    TaskEstimate(Source source, OptionalDouble rate, OptionalDouble etaMillis,
        String scope, int fullTasks, String reason)
    {
        this.source = source;
        this.rate = rate;
        this.etaMillis = etaMillis;
        this.scope = scope;
        this.fullTasks = fullTasks;
        this.reason = reason;
    }

    public Source getSource() { return source; }
    public OptionalDouble getRate() { return rate; }
    public OptionalDouble getEtaMillis() { return etaMillis; }
    public String getScope() { return scope; }
    public int getFullTasks() { return fullTasks; }
    public boolean includesLive() { return source == Source.LIVE || source == Source.BLENDED; }

    public String getDescription()
    {
        switch (source)
        {
            case LIVE: return "Early estimate — this task only";
            case HISTORY: return scope;
            case BLENDED: return scope + " + this task";
            default: return reason;
        }
    }

    public String getCompactDescription()
    {
        if (source == Source.UNAVAILABLE) { return reason; }
        if (source == Source.LIVE) { return "This task — early estimate"; }
        String label = scope.toLowerCase(java.util.Locale.ENGLISH).contains("recent") ? scope
                .replace("recent ", "Recent ").replace(" eligible runs", " runs")
            : "All-time history";
        return label + (source == Source.BLENDED ? " + this task" : "");
    }

    public String getSampleDescription()
    {
        return fullTasks + " fully observed tasks. Total lifetime rate-sample count unavailable.";
    }
}

package com.slayerspeed.calculation;

import java.util.OptionalDouble;

/** No client, clock, persistence or Swing dependencies. */
public final class TaskEstimateService
{
    public TaskEstimate calculate(int remaining, long liveUnits, long liveMillis,
        long historicalUnits, long historicalMillis, int minimumUnits, boolean matches,
        int fullTasks, String scope)
    {
        OptionalDouble history = KphCalculator.ratePerHour(historicalUnits, historicalMillis);
        OptionalDouble live = KphCalculator.ratePerHour(liveUnits, liveMillis);
        boolean hasHistory = history.isPresent() && history.getAsDouble() > 0;
        OptionalDouble rate;
        TaskEstimate.Source source;
        if (matches && liveUnits >= minimumUnits)
        {
            rate = KphCalculator.ratePerHour(historicalUnits + liveUnits, historicalMillis + liveMillis);
            source = hasHistory ? TaskEstimate.Source.BLENDED : TaskEstimate.Source.LIVE;
        }
        else if (hasHistory)
        {
            rate = history;
            source = TaskEstimate.Source.HISTORY;
        }
        else
        {
            rate = matches ? live : OptionalDouble.empty();
            source = TaskEstimate.Source.LIVE;
        }
        OptionalDouble eta = rate.isPresent()
            ? KphCalculator.etaMillis(remaining, rate.getAsDouble()) : OptionalDouble.empty();
        if (!eta.isPresent()) { source = TaskEstimate.Source.UNAVAILABLE; }
        return new TaskEstimate(source, rate, eta, scope, fullTasks,
            matches ? "Waiting for timed task activity" : "No history for this encounter");
    }
}

package com.slayerspeed.model;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.UUID;

public class ActiveTask
{
    private transient boolean suspended;
    public boolean isSuspended() { return suspended; }
    public void markActivity() { suspended = false; }
    public void suspendTiming() { suspended = true; lastActivityAtMillis = 0; }

	private String id;
	private String taskName;
	private String taskLocation;
	private int initialAmount;
	private int observedStartAmount;
	private boolean fullTaskObserved;
	private int lastRemainingAmount;
	private int actualKills;
	private int taskProgressUnits;
	private int killSlayerXp;
	private int bonusSlayerXp;
	private int cannonballsUsed;
	private long activeMillis;
	private long setupMillis;
	private long startedAtMillis;
	private long lastActivityAtMillis;
	private long lastCheckpointAtMillis;
	private long completionConfirmedAtMillis;
	private String manualEncounterProfileId;
	private String manualEncounterProfileName;
	private String detectedEncounterProfileId;
	private String detectedEncounterProfileName;
	private Map<String, Integer> encounterKillsByProfile = new LinkedHashMap<>();
	private Map<String, String> encounterNamesByProfile = new LinkedHashMap<>();

	public ActiveTask()
	{
		// Gson constructor.
	}

	public ActiveTask(String taskName, String taskLocation, int initialAmount, int remainingAmount, long startedAtMillis)
	{
		this.id = UUID.randomUUID().toString();
		this.taskName = taskName;
		this.taskLocation = taskLocation;
		this.initialAmount = initialAmount;
		this.observedStartAmount = remainingAmount;
		this.fullTaskObserved = initialAmount > 0 && remainingAmount == initialAmount;
		this.lastRemainingAmount = remainingAmount;
		this.startedAtMillis = startedAtMillis;
	}

	public TaskKey taskKey(boolean separateByLocation)
	{
		return new TaskKey(taskName, separateByLocation ? taskLocation : null);
	}

	public void addProgressUnits(int units)
	{
		if (units > 0)
		{
			taskProgressUnits += units;
		}
	}

	public void addActualKills(int kills)
	{
		if (kills > 0)
		{
			actualKills += kills;
		}
	}

	public void observeEncounter(EncounterProfile profile)
	{
		if (profile == null || !profile.isKnown())
		{
			return;
		}
		if (encounterKillsByProfile == null)
		{
			encounterKillsByProfile = new LinkedHashMap<>();
		}
		if (encounterNamesByProfile == null)
		{
			encounterNamesByProfile = new LinkedHashMap<>();
		}
		int count = encounterKillsByProfile.getOrDefault(profile.getId(), 0) + 1;
		encounterKillsByProfile.put(profile.getId(), count);
		encounterNamesByProfile.put(profile.getId(), profile.getDisplayName());
		int selectedCount = detectedEncounterProfileId == null
			? 0
			: encounterKillsByProfile.getOrDefault(detectedEncounterProfileId, 0);
		if (detectedEncounterProfileId == null || count >= selectedCount)
		{
			detectedEncounterProfileId = profile.getId();
			detectedEncounterProfileName = profile.getDisplayName();
		}
	}

	public void setManualEncounterProfile(EncounterProfile profile)
	{
		manualEncounterProfileId = profile == null || !profile.isKnown() ? null : profile.getId();
		manualEncounterProfileName = profile == null || !profile.isKnown() ? null : profile.getDisplayName();
	}

	public boolean hasManualEncounterProfile()
	{
		return manualEncounterProfileId != null && !manualEncounterProfileId.isEmpty();
	}

	public String getManualEncounterProfileId()
	{
		return manualEncounterProfileId;
	}

	public String getManualEncounterProfileName()
	{
		return manualEncounterProfileName;
	}

	public String getDetectedEncounterProfileId()
	{
		return detectedEncounterProfileId;
	}

	public String getDetectedEncounterProfileName()
	{
		return detectedEncounterProfileName;
	}

	public String getRecordingEncounterProfileId()
	{
		return hasManualEncounterProfile()
			? manualEncounterProfileId
			: detectedEncounterProfileId;
	}

	public String getRecordingEncounterProfileName()
	{
		return hasManualEncounterProfile()
			? manualEncounterProfileName
			: detectedEncounterProfileName;
	}

	public void addKillSlayerXp(int xp)
	{
		if (xp > 0)
		{
			killSlayerXp += xp;
		}
	}

	public void addBonusSlayerXp(int xp)
	{
		if (xp > 0)
		{
			bonusSlayerXp += xp;
		}
	}

	public void addCannonballsUsed(int cannonballs)
	{
		if (cannonballs > 0)
		{
			cannonballsUsed += cannonballs;
		}
	}

	public void addActiveMillis(long millis)
	{
		if (millis > 0)
		{
			activeMillis += millis;
		}
	}

	public TaskRun finish(TaskRunStatus status, long completedAtMillis)
	{
		return new TaskRun(
			id,
			taskName,
			taskLocation,
			getRecordingEncounterProfileId(),
			getRecordingEncounterProfileName(),
			initialAmount,
			lastRemainingAmount,
			fullTaskObserved,
			actualKills,
			taskProgressUnits,
			killSlayerXp,
			bonusSlayerXp,
			cannonballsUsed,
			activeMillis,
			setupMillis,
			startedAtMillis,
			completedAtMillis,
			status);
	}

	public String getId()
	{
		return id;
	}

	public String getTaskName()
	{
		return taskName;
	}

	public String getTaskLocation()
	{
		return taskLocation;
	}

	public int getInitialAmount()
	{
		return initialAmount;
	}

	public int getObservedStartAmount()
	{
		return observedStartAmount;
	}

	public boolean isFullTaskObserved()
	{
		return fullTaskObserved;
	}

	public void markPartialObservation()
	{
		fullTaskObserved = false;
	}

	public int getLastRemainingAmount()
	{
		return lastRemainingAmount;
	}

	public void setLastRemainingAmount(int lastRemainingAmount)
	{
		this.lastRemainingAmount = lastRemainingAmount;
	}

	public int getActualKills()
	{
		return actualKills;
	}

	public int getTaskProgressUnits()
	{
		return taskProgressUnits;
	}

	public int getKillSlayerXp()
	{
		return killSlayerXp;
	}

	public int getBonusSlayerXp()
	{
		return bonusSlayerXp;
	}

	public int getTotalSlayerXp()
	{
		return killSlayerXp + bonusSlayerXp;
	}

	public int getCannonballsUsed()
	{
		return cannonballsUsed;
	}

	public long getActiveMillis()
	{
		return activeMillis;
	}

	public long getSetupMillis()
	{
		return setupMillis;
	}

	public void setSetupMillis(long setupMillis)
	{
		this.setupMillis = Math.max(0L, setupMillis);
	}

	public long getStartedAtMillis()
	{
		return startedAtMillis;
	}

	public long getLastActivityAtMillis()
	{
		return lastActivityAtMillis;
	}

	public void setLastActivityAtMillis(long lastActivityAtMillis)
	{
		this.lastActivityAtMillis = lastActivityAtMillis;
	}

	public long getLastCheckpointAtMillis()
	{
		return lastCheckpointAtMillis;
	}

	public void setLastCheckpointAtMillis(long lastCheckpointAtMillis)
	{
		this.lastCheckpointAtMillis = lastCheckpointAtMillis;
	}

	public long getCompletionConfirmedAtMillis()
	{
		return completionConfirmedAtMillis;
	}

	public void setCompletionConfirmedAtMillis(long completionConfirmedAtMillis)
	{
		this.completionConfirmedAtMillis = completionConfirmedAtMillis;
	}

	void migrateFromV1()
	{
		fullTaskObserved = initialAmount > 0 && observedStartAmount == initialAmount;
	}

	void migrateFromV4()
	{
		if (encounterKillsByProfile == null)
		{
			encounterKillsByProfile = new LinkedHashMap<>();
		}
		if (encounterNamesByProfile == null)
		{
			encounterNamesByProfile = new LinkedHashMap<>();
		}
	}
}

