package com.slayerspeed.model;

import java.util.LinkedHashMap;
import java.util.Map;

public class SlayerSpeedData
{
	public static final int CURRENT_SCHEMA_VERSION = 5;

	private int schemaVersion = CURRENT_SCHEMA_VERSION;
	private Map<String, TaskStatistics> statisticsByTaskKey = new LinkedHashMap<>();
	private ActiveTask checkpointedActiveTask;

	public int getSchemaVersion()
	{
		return schemaVersion;
	}

	public boolean migrateToCurrentSchema()
	{
		// Schema 6 is accepted only after HistoryValidator verifies ordinary timing.
		if (schemaVersion == 6)
		{
			schemaVersion = CURRENT_SCHEMA_VERSION;
			return true;
		}
		if (schemaVersion < 1 || schemaVersion > CURRENT_SCHEMA_VERSION)
		{
			return false;
		}
		boolean migrated = false;
		if (schemaVersion == 1)
		{
			for (TaskStatistics statistics : getStatisticsByTaskKey().values())
			{
				statistics.migrateFromV1();
			}
			if (checkpointedActiveTask != null)
			{
				checkpointedActiveTask.migrateFromV1();
			}
			schemaVersion = 2;
			migrated = true;
		}
		if (schemaVersion == 2)
		{
			for (TaskStatistics statistics : getStatisticsByTaskKey().values())
			{
				statistics.migrateFromV2();
			}
			schemaVersion = 3;
			migrated = true;
		}
		if (schemaVersion == 3)
		{
			// Cannon fields are additive and safely default to zero for existing histories.
			schemaVersion = 4;
			migrated = true;
		}
		if (schemaVersion == 4)
		{
			for (TaskStatistics statistics : getStatisticsByTaskKey().values())
			{
				statistics.migrateFromV4();
			}
			if (checkpointedActiveTask != null)
			{
				checkpointedActiveTask.migrateFromV4();
			}
			schemaVersion = CURRENT_SCHEMA_VERSION;
			migrated = true;
		}
		return migrated;
	}

	public Map<String, TaskStatistics> getStatisticsByTaskKey()
	{
		if (statisticsByTaskKey == null)
		{
			statisticsByTaskKey = new LinkedHashMap<>();
		}
		return statisticsByTaskKey;
	}

	public ActiveTask getCheckpointedActiveTask()
	{
		return checkpointedActiveTask;
	}

	public void setCheckpointedActiveTask(ActiveTask checkpointedActiveTask)
	{
		this.checkpointedActiveTask = checkpointedActiveTask;
	}
}

package com.slayerspeed.model;

import java.util.Locale;
import java.util.Objects;

public final class TaskKey
{
	private final String taskName;
	private final String taskLocation;
	private final String encounterProfileId;

	public TaskKey(String taskName, String taskLocation)
	{
		this(taskName, taskLocation, EncounterProfile.UNKNOWN_ID);
	}

	public TaskKey(String taskName, String taskLocation, String encounterProfileId)
	{
		this.taskName = normalizeRequired(taskName);
		this.taskLocation = normalizeOptional(taskLocation);
		this.encounterProfileId = normalizeOptional(encounterProfileId);
	}

	private static String normalizeRequired(String value)
	{
		if (value == null || value.trim().isEmpty())
		{
			throw new IllegalArgumentException("Task name is required");
		}
		return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ENGLISH);
	}

	private static String normalizeOptional(String value)
	{
		return value == null || value.trim().isEmpty()
			? ""
			: value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ENGLISH);
	}

	public String getTaskName()
	{
		return taskName;
	}

	public String getTaskLocation()
	{
		return taskLocation;
	}

	public String getEncounterProfileId()
	{
		return encounterProfileId;
	}

	public boolean hasEncounterProfile()
	{
		return !encounterProfileId.isEmpty();
	}

	public String asStorageKey()
	{
		String assignment = taskLocation.isEmpty() ? taskName : taskName + "|" + taskLocation;
		return encounterProfileId.isEmpty()
			? assignment
			: assignment + "|target:" + encounterProfileId;
	}

	@Override
	public boolean equals(Object other)
	{
		if (this == other)
		{
			return true;
		}
		if (!(other instanceof TaskKey))
		{
			return false;
		}
		TaskKey taskKey = (TaskKey) other;
		return taskName.equals(taskKey.taskName)
			&& taskLocation.equals(taskKey.taskLocation)
			&& encounterProfileId.equals(taskKey.encounterProfileId);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(taskName, taskLocation, encounterProfileId);
	}

	@Override
	public String toString()
	{
		return asStorageKey();
	}
}

