package com.slayerspeed.model;

public enum TaskRunStatus
{
	ACTIVE,
	COMPLETED,
	SKIPPED,
	CANCELLED,
	REPLACED,
	UNKNOWN_INCOMPLETE
}

package com.slayerspeed.model;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;

public class TaskStatistics
{
	private String taskName;
	private String taskLocation;
	private String encounterProfileId;
	private String encounterProfileName;
	private int totalActualKills;
	private int totalTaskProgressUnits;
	private int totalSlayerXp;
	private int totalCannonballsUsed;
	private int totalCannonRunActualKills;
	private int totalCannonRunTaskProgressUnits;
	private long totalActiveMillis;
	private long totalCompletedTaskMillis;
	private int completedTaskCount;
	private long lastUpdatedAtMillis;
	private String personalBestRunId;
	private double personalBestEffectiveKph;
	private List<TaskRun> recentRuns = new ArrayList<>();

	public TaskStatistics()
	{
		// Gson constructor.
	}

	public TaskStatistics(String taskName, String taskLocation)
	{
		this(taskName, taskLocation, EncounterProfile.UNKNOWN_ID, EncounterProfile.UNKNOWN_DISPLAY_NAME);
	}

	public TaskStatistics(
		String taskName,
		String taskLocation,
		String encounterProfileId,
		String encounterProfileName)
	{
		this.taskName = taskName;
		this.taskLocation = taskLocation;
		this.encounterProfileId = encounterProfileId;
		this.encounterProfileName = encounterProfileName;
	}

	public void addRun(TaskRun run, int maximumRecentRuns)
	{
		if (isIncludedCompletedRun(run))
		{
			applyRunToAggregates(run, 1);
		}

		if (recentRuns == null)
		{
			recentRuns = new ArrayList<>();
		}
		recentRuns.add(0, run);
		while (recentRuns.size() > Math.max(1, maximumRecentRuns))
		{
			recentRuns.remove(recentRuns.size() - 1);
		}
		lastUpdatedAtMillis = run.getCompletedAtMillis();
		considerPersonalBest(run);
	}

	public void merge(TaskStatistics other)
	{
		totalActualKills += other.totalActualKills;
		totalTaskProgressUnits += other.totalTaskProgressUnits;
		totalSlayerXp += other.totalSlayerXp;
		totalCannonballsUsed += other.totalCannonballsUsed;
		totalCannonRunActualKills += other.totalCannonRunActualKills;
		totalCannonRunTaskProgressUnits += other.totalCannonRunTaskProgressUnits;
		totalActiveMillis += other.totalActiveMillis;
		totalCompletedTaskMillis += other.totalCompletedTaskMillis;
		completedTaskCount += other.completedTaskCount;
		lastUpdatedAtMillis = Math.max(lastUpdatedAtMillis, other.lastUpdatedAtMillis);
		if (other.recentRuns != null)
		{
			if (recentRuns == null)
			{
				recentRuns = new ArrayList<>();
			}
			recentRuns.addAll(other.recentRuns);
			recentRuns.sort(Comparator.comparingLong(TaskRun::getCompletedAtMillis).reversed());
		}
		considerPersonalBest(other.personalBestRunId, other.personalBestEffectiveKph);
	}

	void migrateFromV1()
	{
		// Version 1 treated every completed record as a full task. Preserve its aggregate
		// duration semantics because partial/full provenance cannot be reconstructed.
		totalCompletedTaskMillis = totalActiveMillis;
		if (recentRuns != null)
		{
			for (TaskRun run : recentRuns)
			{
				if (run.getStatus() == TaskRunStatus.COMPLETED)
				{
					run.setFullTaskObserved(true);
				}
			}
		}
	}

	void migrateFromV2()
	{
		recalculatePersonalBest();
	}

	void migrateFromV4()
	{
		if (encounterProfileId == null)
		{
			encounterProfileId = EncounterProfile.UNKNOWN_ID;
		}
		if (encounterProfileName == null || encounterProfileName.trim().isEmpty())
		{
			encounterProfileName = EncounterProfile.UNKNOWN_DISPLAY_NAME;
		}
		if (recentRuns != null)
		{
			for (TaskRun run : recentRuns)
			{
				run.migrateFromV4();
			}
		}
	}

	public boolean setRunExcluded(String runId, boolean excluded)
	{
		TaskRun run = findRecentRun(runId);
		if (run == null
			|| run.getStatus() != TaskRunStatus.COMPLETED
			|| run.isExcludedFromAverages() == excluded)
		{
			return false;
		}
		boolean wasPersonalBest = isPersonalBest(run);
		applyRunToAggregates(run, excluded ? -1 : 1);
		run.setExcludedFromAverages(excluded);
		if (excluded && wasPersonalBest)
		{
			recalculatePersonalBest();
		}
		else if (!excluded)
		{
			considerPersonalBest(run);
		}
		return true;
	}

	public boolean deleteRun(String runId)
	{
		if (recentRuns == null)
		{
			return false;
		}
		for (int index = 0; index < recentRuns.size(); index++)
		{
			TaskRun run = recentRuns.get(index);
			if (run.getId().equals(runId))
			{
				if (isIncludedCompletedRun(run))
				{
					applyRunToAggregates(run, -1);
				}
				recentRuns.remove(index);
				if (isPersonalBest(run))
				{
					recalculatePersonalBest();
				}
				return true;
			}
		}
		return false;
	}

	public boolean isPersonalBest(TaskRun run)
	{
		return run != null && run.getId() != null && run.getId().equals(personalBestRunId);
	}

	private TaskRun findRecentRun(String runId)
	{
		if (recentRuns == null || runId == null)
		{
			return null;
		}
		for (TaskRun run : recentRuns)
		{
			if (runId.equals(run.getId()))
			{
				return run;
			}
		}
		return null;
	}

	private void applyRunToAggregates(TaskRun run, int direction)
	{
		totalActualKills = Math.max(0, totalActualKills + direction * run.getActualKills());
		totalTaskProgressUnits = Math.max(0, totalTaskProgressUnits + direction * run.getTaskProgressUnits());
		totalSlayerXp = Math.max(0, totalSlayerXp + direction * run.getTotalSlayerXp());
		if (run.getCannonballsUsed() > 0)
		{
			totalCannonballsUsed = Math.max(0,
				totalCannonballsUsed + direction * run.getCannonballsUsed());
			totalCannonRunActualKills = Math.max(0,
				totalCannonRunActualKills + direction * run.getActualKills());
			totalCannonRunTaskProgressUnits = Math.max(0,
				totalCannonRunTaskProgressUnits + direction * run.getTaskProgressUnits());
		}
		totalActiveMillis = Math.max(0L, totalActiveMillis + direction * run.getActiveMillis());
		if (run.isFullTaskObserved())
		{
			totalCompletedTaskMillis = Math.max(0L,
				totalCompletedTaskMillis + direction * run.getActiveMillis());
			completedTaskCount = Math.max(0, completedTaskCount + direction);
		}
	}

	private void recalculatePersonalBest()
	{
		personalBestRunId = null;
		personalBestEffectiveKph = 0.0;
		if (recentRuns == null)
		{
			return;
		}
		for (TaskRun run : recentRuns)
		{
			if (isIncludedCompletedRun(run)
				&& run.isFullTaskObserved()
				&& run.getActiveMillis() > 0L)
			{
				considerPersonalBest(run);
			}
		}
	}

	private void considerPersonalBest(TaskRun run)
	{
		if (isIncludedCompletedRun(run) && run.isFullTaskObserved())
		{
			double effectiveKph = run.getActiveMillis() <= 0L
				? 0.0
				: run.getTaskProgressUnits() * 3_600_000.0 / run.getActiveMillis();
			considerPersonalBest(run.getId(), effectiveKph);
		}
	}

	private void considerPersonalBest(String runId, double effectiveKph)
	{
		if (runId != null && Double.isFinite(effectiveKph) && effectiveKph > 0.0
			&& (personalBestRunId == null || effectiveKph > personalBestEffectiveKph))
		{
			personalBestRunId = runId;
			personalBestEffectiveKph = effectiveKph;
		}
	}

	private static boolean isIncludedCompletedRun(TaskRun run)
	{
		return run.getStatus() == TaskRunStatus.COMPLETED && !run.isExcludedFromAverages();
	}

	public String getTaskName()
	{
		return taskName;
	}

	public String getTaskLocation()
	{
		return taskLocation;
	}

	public String getEncounterProfileId()
	{
		return encounterProfileId == null ? EncounterProfile.UNKNOWN_ID : encounterProfileId;
	}

	public String getEncounterProfileName()
	{
		return encounterProfileName == null || encounterProfileName.trim().isEmpty()
			? EncounterProfile.UNKNOWN_DISPLAY_NAME
			: encounterProfileName;
	}

	public int getTotalActualKills()
	{
		return totalActualKills;
	}

	public int getTotalTaskProgressUnits()
	{
		return totalTaskProgressUnits;
	}

	public int getTotalSlayerXp()
	{
		return totalSlayerXp;
	}

	public int getTotalCannonballsUsed()
	{
		return totalCannonballsUsed;
	}

	public int getTotalCannonRunActualKills()
	{
		return totalCannonRunActualKills;
	}

	public int getTotalCannonRunTaskProgressUnits()
	{
		return totalCannonRunTaskProgressUnits;
	}

	public long getTotalActiveMillis()
	{
		return totalActiveMillis;
	}

	public long getTotalCompletedTaskMillis()
	{
		return totalCompletedTaskMillis;
	}

	public int getCompletedTaskCount()
	{
		return completedTaskCount;
	}

	public long getLastUpdatedAtMillis()
	{
		return lastUpdatedAtMillis;
	}

	public List<TaskRun> getRecentRuns()
	{
		return recentRuns == null ? Collections.emptyList() : Collections.unmodifiableList(recentRuns);
	}
}

package com.slayerspeed.mortimer;

import com.slayerspeed.SlayerSpeedConfig;
import com.slayerspeed.calculation.EstimateWindow;
import com.slayerspeed.calculation.HistoryEstimateService;
import com.slayerspeed.calculation.KphCalculator;
import com.slayerspeed.model.EncounterProfile;
import com.slayerspeed.model.TaskKey;
import com.slayerspeed.model.TaskStatistics;
import com.slayerspeed.persistence.TaskHistoryRepository;
import com.slayerspeed.tracking.EncounterProfileResolver;
import java.util.ArrayList;
import java.util.Collection;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.OptionalDouble;
import javax.inject.Inject;

public class MortimerEstimateService
{
	private static final int MAXIMUM_DISPLAYED_PROFILES = 2;
	private static final Map<String, String> HISTORY_TASK_ALIASES = new HashMap<>();

	static
	{
		// Mortimer's UI uses the plural while RuneLite's Slayer service stores the singular.
		HISTORY_TASK_ALIASES.put("bloodvelds", "Bloodveld");
	}

    @Inject private SlayerSpeedConfig config;
	private final TaskHistoryRepository historyRepository;
	private final EncounterProfileResolver encounterProfileResolver;

	@Inject
	public MortimerEstimateService(
		TaskHistoryRepository historyRepository,
		EncounterProfileResolver encounterProfileResolver)
	{
		this.historyRepository = historyRepository;
		this.encounterProfileResolver = encounterProfileResolver;
	}

    public MortimerTaskEstimate estimate(MortimerTaskOffer offer)
    {
        return estimate(offer, config == null ? EstimateWindow.LIFETIME : config.estimateWindow());
    }

    public MortimerTaskEstimate estimate(MortimerTaskOffer offer, EstimateWindow window)
    {
        HistoryEstimateService service = new HistoryEstimateService();
        String historyTaskName = historyTaskName(offer.getTaskName());
		Collection<TaskStatistics> taskHistories = historyRepository.profilesForTask(
			new TaskKey(historyTaskName, null), false);
		List<TaskStatistics> eligible = new ArrayList<>();
		boolean hasKnownProfile = false;
        for (TaskStatistics raw : taskHistories)
        {
            TaskStatistics statistics = service.select(raw, window);
            if (statistics.getTotalTaskProgressUnits() > 0 && statistics.getTotalActiveMillis() > 0)
			{
				eligible.add(statistics);
				hasKnownProfile |= !statistics.getEncounterProfileId().isEmpty();
			}
		}
		if (hasKnownProfile)
		{
			eligible.removeIf(statistics -> statistics.getEncounterProfileId().isEmpty());
		}
		if (eligible.isEmpty())
		{
			return MortimerTaskEstimate.noData();
		}

		boolean labelProfiles = eligible.size() > 1
			|| encounterProfileResolver.suggestionsForTask(historyTaskName).size() > 1;
		List<MortimerTaskEstimate.ProfileEstimate> estimates = new ArrayList<>();
		for (TaskStatistics statistics : eligible)
		{
            OptionalDouble minimumMillis = service.estimate(statistics, window, offer.getMinimumAmount()).getEtaMillis();
            OptionalDouble maximumMillis = service.estimate(statistics, window, offer.getMaximumAmount()).getEtaMillis();
            if (!minimumMillis.isPresent() || !maximumMillis.isPresent()) { continue; }
            estimates.add(new MortimerTaskEstimate.ProfileEstimate(
                labelProfiles ? compactProfileName(statistics) : "",
                formatRange(minimumMillis, maximumMillis), statistics.getCompletedTaskCount(),
                service.scope(statistics, window)));
		}

		if (estimates.isEmpty())
		{
			return MortimerTaskEstimate.noData();
		}
		int additionalProfiles = Math.max(0, estimates.size() - MAXIMUM_DISPLAYED_PROFILES);
		if (additionalProfiles > 0)
		{
			estimates = new ArrayList<>(estimates.subList(0, MAXIMUM_DISPLAYED_PROFILES));
		}
		return new MortimerTaskEstimate(estimates, additionalProfiles);
	}

	static String historyTaskName(String offerTaskName)
	{
		String normalized = offerTaskName == null
			? ""
			: offerTaskName.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ENGLISH);
		return HISTORY_TASK_ALIASES.getOrDefault(normalized, offerTaskName);
	}

	private static String compactProfileName(TaskStatistics statistics)
	{
		if (statistics.getEncounterProfileId().isEmpty())
		{
			return "Mixed";
		}
		String name = statistics.getEncounterProfileName()
			.replaceAll("(?i)\\s*\\((?:regular|boss)\\)$", "")
			.trim();
		return name.isEmpty() || EncounterProfile.UNKNOWN_DISPLAY_NAME.equals(name) ? "Mixed" : name;
	}

	private static String formatRange(OptionalDouble minimumMillis, OptionalDouble maximumMillis)
	{
		if (!minimumMillis.isPresent() || !maximumMillis.isPresent())
		{
			return "--";
		}
		long minimumMinutes = roundedMinutes(minimumMillis.getAsDouble());
		long maximumMinutes = Math.max(minimumMinutes, roundedMinutes(maximumMillis.getAsDouble()));
		if (minimumMinutes == maximumMinutes)
		{
			return "~" + formatMinutes(minimumMinutes);
		}
		return formatMinutes(minimumMinutes) + "-" + formatMinutes(maximumMinutes);
	}

	private static long roundedMinutes(double millis)
	{
		return Math.max(1L, Math.round(millis / 60_000.0));
	}

	private static String formatMinutes(long minutes)
	{
		if (minutes < 60)
		{
			return minutes + "m";
		}
		long hours = minutes / 60;
		long remainingMinutes = minutes % 60;
		return remainingMinutes == 0 ? hours + "h" : hours + "h " + remainingMinutes + "m";
	}
}

package com.slayerspeed.mortimer;

import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;

public class MortimerTaskChoiceParser
{
	// RuneLite 1.12.33 predates the generated SlayerTaskChoice gameval class. Keep this
	// compatibility ID isolated here until the named constant is available in latest.release.
	private static final int CONTENT_PACKED_ID = (236 << 16) | 3;
	private static final Pattern TAG_PATTERN = Pattern.compile("<[^>]*>");
	private static final Pattern AMOUNT_PATTERN = Pattern.compile(
		"(?i)^Amount:\\s*([\\d,]+)\\s*(?:to|-|\\u2013)\\s*([\\d,]+)$");
	private static final Pattern QUANTITY_PATTERN = Pattern.compile(
		"(?i)^\\(?([+-])\\s*([\\d,]+)\\s+Assigned\\)?$");

	private final Client client;

	@Inject
	public MortimerTaskChoiceParser(Client client)
	{
		this.client = client;
	}

	public List<MortimerTaskOffer> readOffers()
	{
		Widget content = client.getWidget(CONTENT_PACKED_ID);
		if (content == null || content.isHidden())
		{
			return new ArrayList<>();
		}

		Widget[] children = content.getDynamicChildren();
		if (children == null || children.length == 0)
		{
			return new ArrayList<>();
		}

		List<Element> elements = new ArrayList<>();
		for (Widget child : children)
		{
			if (child != null && !child.isHidden())
			{
				elements.add(new Element(
					child.getType(), child.getRelativeX(), child.getRelativeY(),
					child.getText(), child.getBounds()));
			}
		}
		return parseElements(elements, content.getBounds());
	}

	static List<MortimerTaskOffer> parseElements(List<Element> elements, Rectangle contentBounds)
	{
		List<MortimerTaskOffer> offers = new ArrayList<>();
		for (Element amountElement : elements)
		{
			if (amountElement.type != WidgetType.TEXT)
			{
				continue;
			}
			Matcher amountMatcher = AMOUNT_PATTERN.matcher(cleanText(amountElement.text));
			if (!amountMatcher.matches())
			{
				continue;
			}

			Element taskElement = findTaskElement(elements, amountElement);
			if (taskElement == null)
			{
				continue;
			}
			int minimum = parseNumber(amountMatcher.group(1));
			int maximum = parseNumber(amountMatcher.group(2));
			int adjustment = findQuantityAdjustment(elements, amountElement.relativeY + 30);
			minimum = Math.max(1, minimum + adjustment);
			maximum = Math.max(minimum, maximum + adjustment);
			Rectangle rowBounds = findRowBounds(elements, amountElement, contentBounds);
			offers.add(new MortimerTaskOffer(
				cleanText(taskElement.text), minimum, maximum, rowBounds));
		}
		offers.sort(Comparator.comparingInt(offer -> offer.getRowBounds().y));
		return offers;
	}

	private static Element findTaskElement(List<Element> elements, Element amountElement)
	{
		Element best = null;
		int expectedY = amountElement.relativeY - 10;
		int bestDistance = Integer.MAX_VALUE;
		for (Element candidate : elements)
		{
			String text = cleanText(candidate.text);
			if (candidate.type != WidgetType.TEXT
				|| candidate.relativeX >= amountElement.relativeX
				|| text.isEmpty()
				|| AMOUNT_PATTERN.matcher(text).matches()
				|| QUANTITY_PATTERN.matcher(text).find())
			{
				continue;
			}
			int distance = Math.abs(candidate.relativeY - expectedY);
			if (distance <= 15 && distance < bestDistance)
			{
				best = candidate;
				bestDistance = distance;
			}
		}
		return best;
	}

	private static int findQuantityAdjustment(List<Element> elements, int expectedY)
	{
		for (Element element : elements)
		{
			if (element.type != WidgetType.TEXT || Math.abs(element.relativeY - expectedY) > 8)
			{
				continue;
			}
			Matcher matcher = QUANTITY_PATTERN.matcher(cleanText(element.text));
			if (matcher.find())
			{
				int amount = parseNumber(matcher.group(2));
				return "-".equals(matcher.group(1)) ? -amount : amount;
			}
		}
		return 0;
	}

	private static Rectangle findRowBounds(
		List<Element> elements,
		Element amountElement,
		Rectangle contentBounds)
	{
		int rowRelativeY = amountElement.relativeY - 15;
		for (Element element : elements)
		{
			if (element.type == WidgetType.RECTANGLE
				&& element.relativeX == 0
				&& Math.abs(element.relativeY - rowRelativeY) <= 2
				&& element.bounds.width > 0
				&& element.bounds.height > 0)
			{
				return new Rectangle(element.bounds);
			}
		}

		Rectangle content = contentBounds == null ? new Rectangle() : contentBounds;
		int rowHeight = Math.max(1, content.height / 3);
		return new Rectangle(
			content.x,
			content.y + Math.max(0, rowRelativeY),
			content.width,
			rowHeight);
	}

	private static int parseNumber(String value)
	{
		try
		{
			return Integer.parseInt(value.replace(",", ""));
		}
		catch (NumberFormatException ex)
		{
			return 0;
		}
	}

	static String cleanText(String value)
	{
		if (value == null)
		{
			return "";
		}
		return TAG_PATTERN.matcher(value)
			.replaceAll("")
			.replace('\u00a0', ' ')
			.trim()
			.replaceAll("\\s+", " ");
	}

	static final class Element
	{
		private final int type;
		private final int relativeX;
		private final int relativeY;
		private final String text;
		private final Rectangle bounds;

		Element(int type, int relativeX, int relativeY, String text, Rectangle bounds)
		{
			this.type = type;
			this.relativeX = relativeX;
			this.relativeY = relativeY;
			this.text = text;
			this.bounds = bounds == null ? new Rectangle() : new Rectangle(bounds);
		}
	}
}

