package com.slayerspeed.ui;

import com.slayerspeed.calculation.KphCalculator;
import com.slayerspeed.model.TaskKey;
import com.slayerspeed.model.TaskRun;
import com.slayerspeed.model.TaskStatistics;
import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.Collection;
import java.util.Collections;
import java.util.OptionalDouble;

public final class StoredStatsDebugFormatter
{
	private static final DateTimeFormatter TIMESTAMP_FORMAT =
		DateTimeFormatter.ofPattern("uuuu-MM-dd HH:mm:ss z");

	private StoredStatsDebugFormatter()
	{
	}

	public static String format(Collection<TaskStatistics> storedStatistics)
	{
		Collection<TaskStatistics> records = storedStatistics == null
			? Collections.emptyList()
			: storedStatistics;
		StringBuilder output = new StringBuilder();
		output.append("Slayer Task Speed - stored task data\n")
			.append("Exact task/location/encounter records: ")
			.append(records.size())
			.append("\n\n");
		if (records.isEmpty())
		{
			return output.append("No stored task statistics.\n").toString();
		}

		int recordNumber = 0;
		for (TaskStatistics statistics : records)
		{
			output.append("=== Record ").append(++recordNumber).append(" ===\n");
			line(output, "Storage key", new TaskKey(
				statistics.getTaskName(),
				statistics.getTaskLocation(),
				statistics.getEncounterProfileId()).asStorageKey());
			line(output, "Task", statistics.getTaskName());
			line(output, "Location", displayOptional(statistics.getTaskLocation()));
			line(output, "Encounter profile", statistics.getEncounterProfileName());
			line(output, "Encounter profile ID", displayOptional(statistics.getEncounterProfileId()));
			line(output, "Completed full tasks", statistics.getCompletedTaskCount());
			line(output, "Actual kills", statistics.getTotalActualKills());
			line(output, "Task progress units", statistics.getTotalTaskProgressUnits());
			line(output, "Slayer XP", statistics.getTotalSlayerXp());
			line(output, "Cannonballs used", statistics.getTotalCannonballsUsed());
			line(output, "Cannon-run kills", statistics.getTotalCannonRunActualKills());
			line(output, "Cannon-run task units", statistics.getTotalCannonRunTaskProgressUnits());
			line(output, "Active milliseconds", statistics.getTotalActiveMillis());
			line(output, "Active duration", formatDuration(statistics.getTotalActiveMillis()));
			line(output, "Full-task milliseconds", statistics.getTotalCompletedTaskMillis());
			line(output, "Full-task duration", formatDuration(statistics.getTotalCompletedTaskMillis()));
			line(output, "Literal KPH", KphCalculator.formatRate(KphCalculator.literalKph(
				statistics.getTotalActualKills(), statistics.getTotalActiveMillis())));
			line(output, "Effective KPH", KphCalculator.formatRate(KphCalculator.effectiveKph(
				statistics.getTotalTaskProgressUnits(), statistics.getTotalActiveMillis())));
			line(output, "Slayer XP/hour", KphCalculator.formatXpRate(KphCalculator.slayerXpPerHour(
				statistics.getTotalSlayerXp(), statistics.getTotalActiveMillis())));
			line(output, "Last updated", formatTimestamp(statistics.getLastUpdatedAtMillis()));
			line(output, "Retained recent runs", statistics.getRecentRuns().size());

			int runNumber = 0;
			for (TaskRun run : statistics.getRecentRuns())
			{
				output.append("  -- Run ").append(++runNumber).append(" --\n");
				runLine(output, "ID", run.getId());
				runLine(output, "Status", run.getStatus());
				runLine(output, "Excluded from averages", run.isExcludedFromAverages());
				runLine(output, "Full task observed", run.isFullTaskObserved());
				runLine(output, "Initial amount", run.getInitialAmount());
				runLine(output, "Ending amount", run.getEndingAmount());
				runLine(output, "Actual kills", run.getActualKills());
				runLine(output, "Task progress units", run.getTaskProgressUnits());
				runLine(output, "Kill Slayer XP", run.getKillSlayerXp());
				runLine(output, "Bonus Slayer XP", run.getBonusSlayerXp());
				runLine(output, "Cannonballs used", run.getCannonballsUsed());
				runLine(output, "Active milliseconds", run.getActiveMillis());
				runLine(output, "Setup milliseconds", run.getSetupMillis());
				runLine(output, "Started", formatTimestamp(run.getStartedAtMillis()));
				runLine(output, "Completed", formatTimestamp(run.getCompletedAtMillis()));
			}
			output.append('\n');
		}
		return output.toString();
	}

	private static void line(StringBuilder output, String name, Object value)
	{
		output.append(name).append(": ").append(value).append('\n');
	}

	private static void runLine(StringBuilder output, String name, Object value)
	{
		output.append("    ").append(name).append(": ").append(value).append('\n');
	}

	private static String displayOptional(String value)
	{
		return value == null || value.trim().isEmpty() ? "<none>" : value;
	}

	private static String formatDuration(long millis)
	{
		return KphCalculator.formatDuration(OptionalDouble.of(Math.max(0L, millis)));
	}

	private static String formatTimestamp(long timestamp)
	{
		return timestamp <= 0L
			? "<none>"
			: TIMESTAMP_FORMAT.format(Instant.ofEpochMilli(timestamp).atZone(ZoneId.systemDefault()));
	}
}

package com.slayerspeed.ui;

import com.slayerspeed.calculation.TaskEstimate;
import com.slayerspeed.calculation.EstimateWindow;
import com.slayerspeed.calculation.HistoryEstimateService;
import com.slayerspeed.calculation.TaskEstimateService;
import com.slayerspeed.calculation.KphCalculator;
import com.slayerspeed.model.TaskStatistics;
import java.awt.BorderLayout;
import java.awt.GridLayout;
import java.util.Collection;
import javax.swing.*;

/** Read-only snapshot. Deliberately has no tracker, repository or mutation callback. */
public final class TaskPreviewPanel extends JPanel
{
    private final JComboBox<Option> choices = new JComboBox<>();
    private final JSpinner amount = new JSpinner(new SpinnerNumberModel(100, 1, 10000, 1));
    private final JLabel result = new JLabel();
    private final JLabel source = new JLabel();
    private final JLabel cannon = new JLabel();
    private final JTextArea samples = new JTextArea(7, 42);

    public TaskPreviewPanel(Collection<TaskStatistics> histories, int remaining)
    {
        this(histories, remaining, EstimateWindow.LIFETIME);
    }

    public TaskPreviewPanel(Collection<TaskStatistics> histories, int remaining, EstimateWindow window)
    {
        super(new BorderLayout(0, 8));
        JPanel controls = new JPanel(new GridLayout(0, 1, 0, 5));
        controls.add(new JLabel("Task / encounter / location"));
        for (TaskStatistics history : histories) { choices.addItem(new Option(history, window)); }
        choices.getAccessibleContext().setAccessibleName("Personal history to preview");
        amount.getAccessibleContext().setAccessibleName("Task units remaining");
        amount.setValue(Math.max(1, Math.min(10000, remaining)));
        controls.add(choices);
        controls.add(new JLabel("Task units remaining"));
        controls.add(amount);
        add(controls, BorderLayout.NORTH);
        JPanel output = new JPanel(new GridLayout(0, 1, 0, 6));
        output.add(result);
        output.add(source);
        output.add(cannon);
        output.add(new JLabel("Preview only — recording is unchanged."));
        add(output, BorderLayout.CENTER);
        samples.setEditable(false);
        samples.setLineWrap(true);
        samples.setWrapStyleWord(true);
        JScrollPane sampleScroll = new JScrollPane(samples);
        sampleScroll.setVisible(false);
        JButton inspect = new JButton("Show estimate samples");
        inspect.addActionListener(event ->
        {
            sampleScroll.setVisible(!sampleScroll.isVisible());
            inspect.setText(sampleScroll.isVisible() ? "Hide estimate samples" : "Show estimate samples");
            java.awt.Window dialogWindow = SwingUtilities.getWindowAncestor(this);
            if (dialogWindow != null) { dialogWindow.pack(); }
        });
        JPanel details = new JPanel(new BorderLayout(0, 5));
        details.add(inspect, BorderLayout.NORTH);
        details.add(sampleScroll, BorderLayout.CENTER);
        add(details, BorderLayout.SOUTH);
        choices.addActionListener(event -> updateEstimate());
        amount.addChangeListener(event -> updateEstimate());
        updateEstimate();
    }

    private void updateEstimate()
    {
        Option option = (Option) choices.getSelectedItem();
        if (option == null)
        {
            result.setText("Complete a task to build personal history.");
            source.setText("");
            cannon.setText("");
            samples.setText("No contributing history.");
            return;
        }
        TaskEstimate estimate = option.estimate((Integer) amount.getValue());
        result.setText(estimate.getEtaMillis().isPresent()
            ? "About " + KphCalculator.formatDuration(estimate.getEtaMillis()) + " of tracked activity"
            : "No timed history for this encounter");
        source.setText(estimate.getDescription());
        samples.setText(option.samples);
        samples.setCaretPosition(0);
        cannon.setText(option.cannonUnits > 0
            ? "If cannoning: about " + KphCalculator.formatCannonballEstimate(
                KphCalculator.estimatedCannonballs((Integer) amount.getValue(),
                    (double) option.balls / option.cannonUnits)) + " cannonballs needed"
            : "No cannon-use history");
    }

    public static final class Option
    {
        private final String label;
        private final String scope;
        private final String samples;
        private final long units;
        private final long millis;
        private final int fullTasks;
        private final int balls;
        private final int cannonUnits;

        public Option(TaskStatistics stats) { this(stats, EstimateWindow.LIFETIME); }

        public Option(TaskStatistics stats, EstimateWindow window)
        {
            HistoryEstimateService service = new HistoryEstimateService();
            stats = service.select(stats, window);
            scope = service.scope(stats, window);
            label = stats.getTaskName() + " / " + stats.getEncounterProfileName()
                + " / " + (stats.getTaskLocation() == null ? "Unspecified location" : stats.getTaskLocation());
            StringBuilder detail = new StringBuilder(window == null || window == EstimateWindow.LIFETIME
                ? "Retained records only. Lifetime totals can also include pruned records.\n"
                : "Every eligible run contributing to this estimate:\n");
            java.time.format.DateTimeFormatter date = java.time.format.DateTimeFormatter.ofPattern("d MMM yyyy HH:mm");
            for (com.slayerspeed.model.TaskRun run : stats.getRecentRuns())
            {
                detail.append(date.format(java.time.Instant.ofEpochMilli(run.getCompletedAtMillis())
                    .atZone(java.time.ZoneId.systemDefault()))).append(" — ")
                    .append(run.getTaskProgressUnits()).append(" timed units, ")
                    .append(KphCalculator.formatDuration(java.util.OptionalDouble.of(run.getActiveMillis())))
                    .append(run.isFullTaskObserved() ? ", full task" : ", partial")
                    .append(run.isExcludedFromAverages() ? ", excluded" : "")
                    .append(", ").append(run.getStatus()).append("\n");
            }
            samples = detail.toString();
            units = stats.getTotalTaskProgressUnits();
            millis = stats.getTotalActiveMillis();
            fullTasks = stats.getCompletedTaskCount();
            balls = stats.getTotalCannonballsUsed();
            cannonUnits = stats.getTotalCannonRunTaskProgressUnits();
        }

        public TaskEstimate estimate(int remaining)
        {
            return new TaskEstimateService().calculate(remaining, 0, 0, units, millis,
                10, false, fullTasks, scope);
        }

        @Override public String toString() { return label; }
    }
}

package com.slayerspeed;

import com.google.gson.Gson;
import com.google.inject.AbstractModule;
import com.google.inject.Guice;
import com.slayerspeed.persistence.TaskHistoryRepository;
import com.slayerspeed.tracking.*;
import com.slayerspeed.ui.*;
import java.util.*;
import javax.swing.SwingUtilities;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.plugins.slayer.SlayerPluginService;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.infobox.InfoBox;
import net.runelite.client.ui.overlay.infobox.InfoBoxManager;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

/** Tests our lifecycle callbacks with injected services, not RuneLite's private machinery. */
public class SlayerSpeedPluginLifecycleTest
{
    private final SlayerSpeedPlugin plugin = new SlayerSpeedPlugin();
    private final Client client = mock(Client.class);
    private final SlayerPluginService slayer = mock(SlayerPluginService.class);
    private final ConfigManager configManager = mock(ConfigManager.class);
    private final OverlayManager overlays = mock(OverlayManager.class);
    private final ClientToolbar toolbar = mock(ClientToolbar.class);
    private final ClientThread clientThread = mock(ClientThread.class);
    private final InfoBoxManager infoBoxManager = mock(InfoBoxManager.class);
    private final List<InfoBox> boxes = new ArrayList<>();
    private final Queue<Runnable> clientTasks = new ArrayDeque<>();
    private final TaskHistoryRepository repository = new TaskHistoryRepository(configManager, new Gson());
    private final TaskTracker tracker = new TaskTracker(repository, new ActiveTimeTracker());
    private String profile = "account-a";
    private int tick;
    private boolean showInfoBoxes = true;
    private NavigationButton navigation;

    @Before public void setUp() throws Exception
    {
        when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
        when(client.getTickCount()).thenAnswer(call -> tick);
        when(client.getItemContainer(anyInt())).thenAnswer(call ->
        {
            assertFalse("Inventory reads must not run on the EDT", SwingUtilities.isEventDispatchThread());
            return null;
        });
        when(client.getVarpValue(anyInt())).thenAnswer(call ->
        {
            assertFalse("Varp reads must not run on the EDT", SwingUtilities.isEventDispatchThread());
            return 0;
        });
        when(slayer.getTask()).thenReturn("Gargoyles");
        when(slayer.getInitialAmount()).thenReturn(100);
        when(slayer.getRemainingAmount()).thenReturn(100);
        when(slayer.getTargets()).thenReturn(Collections.emptyList());
        Map<String, String> storage = new HashMap<>();
        when(configManager.getRSProfileKey()).thenAnswer(call -> profile);
        when(configManager.getRSProfileConfiguration(eq(SlayerSpeedConfig.GROUP), anyString()))
            .thenAnswer(call -> storage.get(profile + ":" + call.getArgument(1)));
        doAnswer(call ->
        {
            storage.put(profile + ":" + call.getArgument(1), String.valueOf((Object) call.getArgument(2)));
            return null;
        }).when(configManager).setRSProfileConfiguration(eq(SlayerSpeedConfig.GROUP), anyString(), any());
        doAnswer(call -> { clientTasks.add(call.getArgument(0)); return null; })
            .when(clientThread).invoke(any(Runnable.class));
        doAnswer(call -> { navigation = call.getArgument(0); return null; })
            .when(toolbar).addNavigation(any(NavigationButton.class));
        doAnswer(call -> { boxes.add(call.getArgument(0)); return null; })
            .when(infoBoxManager).addInfoBox(any(InfoBox.class));
        doAnswer(call -> { boxes.remove(call.getArgument(0)); return null; })
            .when(infoBoxManager).removeInfoBox(any(InfoBox.class));
        SlayerSpeedConfig config = new SlayerSpeedConfig()
        {
            @Override public boolean showInfoBoxes() { return showInfoBoxes; }
            @Override public boolean infoBoxKillsPerHour() { return true; }
            @Override public boolean infoBoxSlayerXpPerHour() { return true; }
        };
        Guice.createInjector(new AbstractModule()
        {
            @Override protected void configure()
            {
                bind(SlayerSpeedPlugin.class).toInstance(plugin);
                bind(Client.class).toInstance(client);
                bind(SlayerSpeedConfig.class).toInstance(config);
                bind(ConfigManager.class).toInstance(configManager);
                bind(SlayerPluginService.class).toInstance(slayer);
                bind(TaskTracker.class).toInstance(tracker);
                bind(TaskHistoryRepository.class).toInstance(repository);
                bind(OverlayManager.class).toInstance(overlays);
                bind(ClientToolbar.class).toInstance(toolbar);
                bind(ClientThread.class).toInstance(clientThread);
                bind(InfoBoxManager.class).toInstance(infoBoxManager);
                bind(MortimerChoiceOverlay.class).toInstance(mock(MortimerChoiceOverlay.class));
            }
        });
        SwingUtilities.invokeAndWait(plugin::startUp);
        flush();
        // Seed an old assignment through the tracker's public time-aware API.
        tracker.observe(TaskSnapshot.active("Gargoyles", null, 100, 100),
            System.currentTimeMillis() - 180_000L, 5, true, 50);
        gameTick();
    }

    @After public void tearDown() throws Exception
    {
        if (plugin.isRunning()) { SwingUtilities.invokeAndWait(plugin::shutDown); }
        flush();
    }

    @Test public void shutdownRemovesDisplaysBeforeCleanupEvenIfInventoryIsUnavailable() throws Exception
    {
        progress();
        assertTrue(plugin.isOverlayVisible());
        when(client.getItemContainer(anyInt())).thenThrow(new IllegalStateException("Inventory unavailable"));
        SwingUtilities.invokeAndWait(plugin::shutDown);
        assertFalse(plugin.isRunning());
        assertFalse(plugin.isOverlayVisible());
        assertFalse(plugin.getViewModel().isActive());
        assertTrue(boxes.isEmpty());
        verify(overlays, times(2)).remove(any(net.runelite.client.ui.overlay.Overlay.class));
        verify(toolbar).removeNavigation(navigation);
        assertFalse(clientTasks.isEmpty());
        flush();
        assertTrue(tracker.getActiveTask().isSuspended());
    }

    @Test public void logoutAndAccountSwitchCannotDisplayThePreviousTask() throws Exception
    {
        progress();
        for (GameState state : new GameState[] {GameState.LOGIN_SCREEN, GameState.HOPPING, GameState.CONNECTION_LOST})
        {
            GameStateChanged event = new GameStateChanged();
            event.setGameState(state);
            when(client.getGameState()).thenReturn(state);
            plugin.onGameStateChanged(event);
            assertFalse(plugin.isOverlayVisible());
            assertTrue(boxes.stream().noneMatch(InfoBox::render));
        }
        profile = "account-b";
        plugin.onRuneScapeProfileChanged(new RuneScapeProfileChanged("account-a", profile));
        flush();
        assertNull(tracker.getActiveTask());
        assertFalse(plugin.getViewModel().isActive());
        assertEquals(profile, repository.getProfileIdentity());
    }

    @Test public void idleDisplaysReturnOnProgressAndHideOnCompletion() throws Exception
    {
        assertFalse(plugin.isOverlayVisible());
        assertTrue(plugin.getViewModel().isActive());
        assertTrue(boxes.stream().noneMatch(InfoBox::render));
        progress();
        assertTrue(plugin.isOverlayVisible());
        assertTrue(boxes.stream().allMatch(InfoBox::render));
        ChatMessage completion = new ChatMessage();
        completion.setType(ChatMessageType.GAMEMESSAGE);
        completion.setMessage("You have completed your task!");
        plugin.onChatMessage(completion);
        assertTrue(tracker.isCompletionPending());
        assertFalse(plugin.isOverlayVisible());
        assertTrue(boxes.stream().noneMatch(InfoBox::render));
    }

    @Test public void sidebarInteractionRestoresVisibilityWithoutInventingTaskProgress() throws Exception
    {
        SwingUtilities.invokeAndWait(navigation.getPanel()::onActivate);
        flush();
        assertTrue(plugin.isOverlayVisible());
        assertEquals(0, tracker.getActiveTask().getTaskProgressUnits());
        assertEquals(0L, tracker.getActiveTask().getActiveMillis());
    }

    @Test public void targetCombatKeepsAnIdleDisplayVisibleWithoutAKill() throws Exception
    {
        assertFalse(plugin.isOverlayVisible());
        NPC target = mock(NPC.class);
        Player player = mock(Player.class);
        when(player.getInteracting()).thenReturn(target);
        when(client.getLocalPlayer()).thenReturn(player);
        when(slayer.getTargets()).thenReturn(Collections.singletonList(target));
        gameTick();
        assertTrue(plugin.isOverlayVisible());
        assertEquals(0, tracker.getActiveTask().getTaskProgressUnits());
    }

    @Test public void infoboxSettingsApplyWithoutDuplicateRegistration() throws Exception
    {
        gameTick();
        assertEquals(3, boxes.size());
        assertEquals(3, boxes.stream().map(InfoBox::getName).distinct().count());
        ConfigChanged event = new ConfigChanged();
        event.setGroup(SlayerSpeedConfig.GROUP);
        event.setKey("showInfoBoxes");
        showInfoBoxes = false;
        plugin.onConfigChanged(event);
        flush();
        assertTrue(boxes.isEmpty());
        assertTrue(plugin.getViewModel().isActive());
        showInfoBoxes = true;
        plugin.onConfigChanged(event);
        flush();
        assertEquals(3, boxes.size());
    }

    @Test public void rapidRestartDiscardsStaleInitializationAndPreservesCheckpoint() throws Exception
    {
        String taskId = tracker.getActiveTask().getId();
        SwingUtilities.invokeAndWait(plugin::shutDown);
        flush();
        clearInvocations(client);
        SwingUtilities.invokeAndWait(() ->
        {
            plugin.startUp();
            plugin.shutDown();
            plugin.startUp();
        });
        gameTick();
        assertTrue(plugin.isRunning());
        assertEquals(taskId, tracker.getActiveTask().getId());
        assertEquals(3, boxes.size());
        verify(client, times(2)).getVarpValue(anyInt());
    }

    private void progress() throws Exception
    {
        when(slayer.getRemainingAmount()).thenReturn(99);
        gameTick();
    }
    private void gameTick() throws Exception
    {
        drain();
        tick++;
        plugin.onGameTick(new GameTick());
        flush();
    }
    private void flush() throws Exception { drain(); SwingUtilities.invokeAndWait(() -> {}); }
    private void drain()
    {
        Runnable task;
        while ((task = clientTasks.poll()) != null) { task.run(); }
    }
}

package com.slayerspeed;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class SlayerSpeedPluginTest
{
    @Test
    public void overlayExpiresAtTimeoutAndReturnsOnFreshActivity()
    {
        long activity = 1_000_000L;
        assertTrue(SlayerSpeedPlugin.isOverlayRecent(activity, activity, 2));
        assertTrue(SlayerSpeedPlugin.isOverlayRecent(activity + 119_999L, activity, 2));
        assertFalse(SlayerSpeedPlugin.isOverlayRecent(activity + 120_000L, activity, 2));
        assertFalse(SlayerSpeedPlugin.isOverlayRecent(activity + 900_000L, activity, 2));
        assertTrue(SlayerSpeedPlugin.isOverlayRecent(activity + 900_000L, activity + 900_000L, 2));
    }

    @Test
    public void overlayTimeoutCanBeConfiguredWithoutChangingTrackingTimeout()
    {
        assertTrue(SlayerSpeedPlugin.isOverlayRecent(900_000L, 1L, 0));
        assertFalse(SlayerSpeedPlugin.isOverlayRecent(900_000L, 1L, 1));
        assertTrue(SlayerSpeedPlugin.isOverlayRecent(900_000L, 1L, 30));
        assertFalse(SlayerSpeedPlugin.isOverlayRecent(900_000L, 0L, 2));
        assertTrue(SlayerSpeedPlugin.isOverlayRecent(900_000L, 900_001L, 2));
    }

	@Test
	public void recognizesOnlyExplicitTaskCompletionMessages()
	{
		assertTrue(SlayerSpeedPlugin.isTaskCompletionMessage("You have completed your task!"));
		assertTrue(SlayerSpeedPlugin.isTaskCompletionMessage("  YOU HAVE COMPLETED YOUR TASK!  "));
		assertFalse(SlayerSpeedPlugin.isTaskCompletionMessage("You have completed a combat task!"));
		assertFalse(SlayerSpeedPlugin.isTaskCompletionMessage(null));
	}

	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(SlayerSpeedPlugin.class);
		RuneLite.main(args);
	}
}

package com.slayerspeed.calculation;

import com.slayerspeed.model.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class HistoryEstimateServiceTest
{
    private final HistoryEstimateService service = new HistoryEstimateService();
    private TaskRun run(String id, int units, long time, long ended, TaskRunStatus status, boolean full, int balls)
    {
        return new TaskRun(id, "Gargoyles", null, "", "Mixed", units, 0, full,
            units, units, units * 100, 0, balls, time, 0, 0, ended, status);
    }

    @Test public void filtersBeforeLimitingAndDoesNotBackfillFromLifetime()
    {
        TaskStatistics history = new TaskStatistics("Gargoyles", null);
        history.addRun(run("old", 900, 900000, 1, TaskRunStatus.COMPLETED, true, 0), 2);
        history.addRun(run("partial", 20, 60000, 2, TaskRunStatus.COMPLETED, false, 40), 2);
        history.addRun(run("skip", 90, 60000, 3, TaskRunStatus.SKIPPED, true, 900), 2);
        TaskStatistics selected = service.select(history, EstimateWindow.RECENT_5);
        assertEquals(1, selected.getRecentRuns().size());
        assertEquals(20, selected.getTotalTaskProgressUnits());
